<script setup lang="ts">
import { ref, watch, nextTick, onBeforeUnmount } from 'vue'
import { Camera } from '@element-plus/icons-vue'
import { api, errorText } from '../api'
import { useCamera } from '../composables'
import { ElMessage } from 'element-plus'
const props=defineProps<{modelValue:boolean;employee:any}>(),emit=defineEmits(['update:modelValue','saved'])
const {video,cameraReady,cameraError,start,stop,frame}=useCamera(),consent=ref(false),photos=ref<{blob:Blob;url:string}[]>([]),loading=ref(false),capturing=ref(false),error=ref(''),poses=['正脸','轻微左转','轻微右转']
let generation=0
function clear(){generation++;stop();photos.value.forEach(p=>URL.revokeObjectURL(p.url));photos.value=[];consent.value=false;capturing.value=false;error.value=''}
watch(()=>props.modelValue,async open=>{if(!open)clear();else{clear();await nextTick()}})
async function capture(){if(capturing.value||!consent.value||!cameraReady.value||photos.value.length>=3||!props.modelValue)return;const current=generation;capturing.value=true;try{const blob=await frame();if(current!==generation||!props.modelValue)return;if(!blob){error.value='未获取到清晰画面，请稍后重试';return}photos.value.push({blob,url:URL.createObjectURL(blob)});if(photos.value.length===3)stop()}catch(e){if(current===generation)error.value=errorText(e)}finally{if(current===generation)capturing.value=false}}
async function reset(){generation++;photos.value.forEach(p=>URL.revokeObjectURL(p.url));photos.value=[];capturing.value=false;error.value='';await start()}
async function save(){if(photos.value.length!==3||!consent.value)return;loading.value=true;error.value='';try{const form=new FormData();photos.value.forEach((p,i)=>form.append('files',p.blob,`${['FRONT','LEFT','RIGHT'][i]}.jpg`));form.append('consent','true');await api(`/employees/${props.employee.id}/face`,{method:'POST',body:form});ElMessage.success('人脸模板录入成功');emit('saved');emit('update:modelValue',false)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
onBeforeUnmount(clear)
</script>
<template><el-dialog :model-value="modelValue" :title="`现场人脸录入 · ${employee?.name||''}`" width="650px" :close-on-click-modal="false" :close-on-press-escape="!loading" :show-close="!loading" @update:model-value="emit('update:modelValue',$event)"><p class="help-text">请管理员现场核对员工身份。依次采集正脸、轻微左转、轻微右转各一张；系统将检查图像质量、人员一致性与重复绑定。成功后整体替换该员工的旧模板。</p><el-alert v-if="error||cameraError" :title="error||cameraError" type="error" show-icon :closable="false"/><el-checkbox v-model="consent" :disabled="cameraReady||photos.length>0">已告知用途、保存期限、删除方式及人工替代方式，并取得本人单独同意</el-checkbox><div class="camera-shell" style="margin-top:18px"><video ref="video" muted autoplay playsinline/><div v-if="!cameraReady" class="camera-placeholder"><el-icon :size="40"><Camera/></el-icon><span>{{photos.length===3?'三张图像已采集，等待提交检查':'确认同意后打开摄像头'}}</span></div><div v-if="cameraReady" class="camera-guide"/><div v-if="cameraReady" class="camera-caption">第 {{photos.length+1}} / 3 张 · {{poses[photos.length]}}</div></div><div class="photo-strip"><div v-for="(pose,i) in poses" :key="pose" class="photo-item"><img v-if="photos[i]" :src="photos[i].url" :alt="pose+'采集预览'"><div v-else class="photo-empty">{{i+1}}</div>{{pose}}</div></div><div class="camera-actions"><el-button v-if="!cameraReady && photos.length===0" :disabled="!consent" :icon="Camera" type="primary" @click="start">打开摄像头</el-button><el-button v-if="cameraReady" type="primary" :loading="capturing" @click="capture">采集{{poses[photos.length]}}</el-button><el-button v-if="photos.length" :disabled="loading||capturing" @click="reset">重新采集</el-button></div><p class="help-text">仅保存加密的人脸特征，不保存采集原图。关闭窗口后立即释放摄像头并清除本次照片。</p><template #footer><el-button :disabled="loading" @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" :disabled="photos.length!==3||!consent" :loading="loading" @click="save">提交并验证</el-button></template></el-dialog></template>
